    db.put({.sync = false}, to_bytes("k1"), to_bytes("v1"));
    db.put({.sync = false}, to_bytes("k2"), to_bytes("v2"));
    db.put({.sync = false}, to_bytes("k3"), to_bytes("v3"));
    db.put({.sync = false}, to_bytes("k4"), to_bytes("v4"));
